/**
 * The slice of Orca's plugin API this plugin uses. Orca ships fuller author typings
 * (`orca/worker`, `orca/frame`, generated by `orca plugin types`), but they cannot be
 * imported as values and change with Orca, so this plugin types only what it calls.
 * Shapes follow stablyai/orca `resources/plugins/types/orca-{worker,frame,host}.d.ts`.
 */

export type Disposable = { dispose(): void };

export type PanelRequestContext = {
  panel: { id: string };
  /** Aborts when the request times out or its panel closes. */
  signal: AbortSignal;
};

/** The `orca` object `activate(orca)` receives in a `trusted-worker`. */
export type OrcaWorkerApi = {
  readonly host: {
    call(method: string, params?: unknown): Promise<unknown>;
    has(method: string): boolean;
  };
  readonly panels: {
    handle(
      name: string,
      handler: (input: unknown, context: PanelRequestContext) => unknown
    ): Disposable;
    /** To every open panel of this plugin. Fire and forget: at most 256 KiB, 200 per 10 s. */
    post(event: string, payload?: unknown, options?: { panel?: string }): void;
  };
  readonly storage: {
    get(key: string): Promise<unknown>;
    set(key: string, value: unknown): Promise<unknown>;
  };
  readonly events: {
    on(event: string, handler: (payload: unknown) => void | Promise<void>): Disposable;
  };
  log(message: string): void;
};

/** What a frame's `window.orca.plugin` offers: the plugin's own worker. */
export type FramePluginBridge = {
  /** Rejects with `unknown_method`, `timeout`, `unavailable`, or the handler's error code. */
  request(name: string, input?: unknown, options?: { timeoutMs?: number }): Promise<unknown>;
  on(event: string, handler: (payload: unknown) => void): Disposable;
};

/** `window.orca` in a panel frame. */
export type OrcaFrameApi = {
  readonly plugin: FramePluginBridge;
  /** Orca's UI language as a BCP-47 tag. */
  readonly locale: string;
  readonly shell?: {
    openExternal(url: string): Promise<{ opened: boolean }>;
  };
};
